@using sv_5f63decaec9d417abd18e328d40dbba1.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @* ── Step Indicator Bar ── *@
    <nav class="d-flex justify-content-between mb-4 position-relative">
        @for (int i = 0; i < _stepNames.Length; i++)
        {
            var step = i + 1;
            var isCompleted = _completedSteps.Contains(step);
            var isCurrent = step == _currentStep;
            var isFuture = step > _currentStep && !isCompleted;

            <div class="text-center flex-fill position-relative">
                <button type="button"
                        class="btn rounded-circle d-inline-flex align-items-center justify-content-center @(isCurrent ? "btn-primary" : isCompleted ? "btn-success" : "btn-outline-secondary")"
                        style="width: 40px; height: 40px; font-size: 0.85rem;"
                        disabled="@(isFuture && !isCompleted)"
                        @onclick="() => GoToStep(step)">
                    @if (isCompleted && !isCurrent)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        @step
                    }
                </button>
                <div class="small mt-1 @(isFuture ? "text-muted" : "")">@_stepNames[i]</div>
            </div>
        }
    </nav>

    @if (_submitted)
    {
        <div class="alert alert-success text-center">
            <h4 class="alert-heading">Application Submitted!</h4>
            <p>Your application has been received. Your application ID is <strong>#@_applicationId</strong>.</p>
            <p class="mb-0">We will review your application and get back to you soon.</p>
        </div>
    }
    else
    {
        @* ── Validation errors ── *@
        @if (_errors.Count > 0)
        {
            <div class="alert alert-danger">
                <ul class="mb-0">
                    @foreach (var error in _errors)
                    {
                        <li>@error</li>
                    }
                </ul>
            </div>
        }

        @* ── Step 1: Personal Info ── *@
        @if (_currentStep == 1)
        {
            <h4>Personal Information</h4>
            <div class="mb-3">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input type="text" class="form-control" @bind="_fullName" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="_email" />
            </div>
            <div class="mb-3">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input type="tel" class="form-control" @bind="_phone" />
            </div>
            <div class="mb-3">
                <label class="form-label">Address <span class="text-danger">*</span></label>
                <input type="text" class="form-control" @bind="_address" />
            </div>
            <div class="d-flex justify-content-end">
                <button class="btn btn-primary" @onclick="NextStep" disabled="@_isProcessing">
                    @if (_isProcessing) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Next
                </button>
            </div>
        }

        @* ── Step 2: Work History ── *@
        @if (_currentStep == 2)
        {
            <h4>Work History</h4>
            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var index = i;
                var entry = _workEntries[index];
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h6 class="mb-0">Position @(index + 1)</h6>
                            @if (_workEntries.Count > 1)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                            }
                        </div>
                        <div class="mb-2">
                            <label class="form-label">Company Name <span class="text-danger">*</span></label>
                            <input type="text" class="form-control" @bind="entry.Company" />
                        </div>
                        <div class="mb-2">
                            <label class="form-label">Job Title <span class="text-danger">*</span></label>
                            <input type="text" class="form-control" @bind="entry.Title" />
                        </div>
                        <div class="row mb-2">
                            <div class="col-md-6">
                                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                <input type="date" class="form-control" @bind="entry.StartDate" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">End Date</label>
                                <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                                <div class="form-check mt-1">
                                    <input type="checkbox" class="form-check-input" id="current-@index" @bind="entry.IsCurrent" />
                                    <label class="form-check-label" for="current-@index">I currently work here</label>
                                </div>
                            </div>
                        </div>
                        <div class="mb-2">
                            <label class="form-label">Description</label>
                            <textarea class="form-control" rows="2" @bind="entry.Description"></textarea>
                        </div>
                    </div>
                </div>
            }
            <button class="btn btn-outline-primary btn-sm mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next</button>
            </div>
        }

        @* ── Step 3: References ── *@
        @if (_currentStep == 3)
        {
            <h4>References</h4>
            @for (int i = 0; i < _references.Count; i++)
            {
                var index = i;
                var reference = _references[index];
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h6 class="mb-0">Reference @(index + 1)</h6>
                            @if (_references.Count > 2)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                            }
                        </div>
                        <div class="row mb-2">
                            <div class="col-md-6">
                                <label class="form-label">Name <span class="text-danger">*</span></label>
                                <input type="text" class="form-control" @bind="reference.Name" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Relationship <span class="text-danger">*</span></label>
                                <input type="text" class="form-control" @bind="reference.Relationship" />
                            </div>
                        </div>
                        <div class="row mb-2">
                            <div class="col-md-6">
                                <label class="form-label">Email <span class="text-danger">*</span></label>
                                <input type="email" class="form-control" @bind="reference.Email" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Phone <span class="text-danger">*</span></label>
                                <input type="tel" class="form-control" @bind="reference.Phone" />
                            </div>
                        </div>
                    </div>
                </div>
            }
            @if (_references.Count < 3)
            {
                <button class="btn btn-outline-primary btn-sm mb-3" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next</button>
            </div>
        }

        @* ── Step 4: Cover Letter ── *@
        @if (_currentStep == 4)
        {
            <h4>Cover Letter</h4>
            <div class="mb-3">
                <textarea class="form-control" rows="10" maxlength="2000"
                          @bind="_coverLetter" @bind:event="oninput"></textarea>
                <div class="form-text text-end">@(_coverLetter?.Length ?? 0) / 2000 characters</div>
            </div>
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next</button>
            </div>
        }

        @* ── Step 5: Review & Submit ── *@
        @if (_currentStep == 5)
        {
            <h4>Review &amp; Submit</h4>

            @* Personal Info *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Personal Information</strong>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(1)">Edit</button>
                </div>
                <div class="card-body">
                    <dl class="row mb-0">
                        <dt class="col-sm-3">Full Name</dt><dd class="col-sm-9">@_fullName</dd>
                        <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                        <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                        <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                    </dl>
                </div>
            </div>

            @* Work History *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Work History</strong>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(2)">Edit</button>
                </div>
                <div class="card-body">
                    @foreach (var entry in _workEntries)
                    {
                        <div class="mb-3">
                            <strong>@entry.Title</strong> at @entry.Company<br />
                            <span class="text-muted">
                                @entry.StartDate.ToString("MMM yyyy") &ndash;
                                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                            </span>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="mt-1 mb-0">@entry.Description</p>
                            }
                        </div>
                    }
                </div>
            </div>

            @* References *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>References</strong>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(3)">Edit</button>
                </div>
                <div class="card-body">
                    @foreach (var r in _references)
                    {
                        <div class="mb-2">
                            <strong>@r.Name</strong> (@r.Relationship)<br />
                            <span class="text-muted">@r.Email &bull; @r.Phone</span>
                        </div>
                    }
                </div>
            </div>

            @* Cover Letter *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Cover Letter</strong>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(4)">Edit</button>
                </div>
                <div class="card-body">
                    <p style="white-space: pre-wrap;">@_coverLetter</p>
                </div>
            </div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isProcessing">
                    @if (_isProcessing) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Submit Application
                </button>
            </div>
        }
    }
</div>

@code {
    private static readonly string[] _stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int _currentStep = 1;
    private readonly HashSet<int> _completedSteps = new();
    private List<string> _errors = new();
    private bool _isProcessing;
    private bool _submitted;
    private int _applicationId;

    // Step 1
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        if (_completedSteps.Contains(step) || step == _currentStep)
        {
            _errors.Clear();
            _currentStep = step;
        }
    }

    private void PreviousStep()
    {
        _errors.Clear();
        _currentStep--;
    }

    private async Task NextStep()
    {
        _errors.Clear();
        if (!await ValidateCurrentStep()) return;

        _completedSteps.Add(_currentStep);
        _currentStep++;
    }

    private async Task<bool> ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 1:
                if (string.IsNullOrWhiteSpace(_fullName)) _errors.Add("Full name is required.");
                if (string.IsNullOrWhiteSpace(_email)) _errors.Add("Email is required.");
                if (string.IsNullOrWhiteSpace(_phone)) _errors.Add("Phone is required.");
                if (string.IsNullOrWhiteSpace(_address)) _errors.Add("Address is required.");
                if (_errors.Count > 0) return false;

                _isProcessing = true;
                StateHasChanged();
                var emailValid = await ApplicationService.ValidateEmailAsync(_email);
                _isProcessing = false;
                if (!emailValid)
                {
                    _errors.Add("Please enter a valid email address.");
                    return false;
                }
                break;

            case 2:
                for (int i = 0; i < _workEntries.Count; i++)
                {
                    var e = _workEntries[i];
                    if (string.IsNullOrWhiteSpace(e.Company)) _errors.Add($"Position {i + 1}: Company name is required.");
                    if (string.IsNullOrWhiteSpace(e.Title)) _errors.Add($"Position {i + 1}: Job title is required.");
                    if (e.StartDate == default) _errors.Add($"Position {i + 1}: Start date is required.");
                }
                break;

            case 3:
                for (int i = 0; i < _references.Count; i++)
                {
                    var r = _references[i];
                    if (string.IsNullOrWhiteSpace(r.Name)) _errors.Add($"Reference {i + 1}: Name is required.");
                    if (string.IsNullOrWhiteSpace(r.Relationship)) _errors.Add($"Reference {i + 1}: Relationship is required.");
                    if (string.IsNullOrWhiteSpace(r.Email)) _errors.Add($"Reference {i + 1}: Email is required.");
                    if (string.IsNullOrWhiteSpace(r.Phone)) _errors.Add($"Reference {i + 1}: Phone is required.");
                }
                break;

            case 4:
                if (string.IsNullOrWhiteSpace(_coverLetter)) _errors.Add("Cover letter is required.");
                break;
        }

        return _errors.Count == 0;
    }

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (_workEntries.Count > 1) _workEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (_references.Count < 3) _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2) _references.RemoveAt(index);
    }

    private async Task SubmitApplication()
    {
        _isProcessing = true;
        StateHasChanged();

        var application = new JobApplication(
            new PersonalInfo(_fullName, _email, _phone, _address),
            new WorkHistory(_workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description ?? "")
            ).ToList()),
            _references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)
            ).ToList(),
            _coverLetter
        );

        _applicationId = await ApplicationService.SubmitApplicationAsync(application);
        _isProcessing = false;
        _submitted = true;
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string? Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

